{
  "findings": [
    {
      "check_id": "CKV_AWS_88",
      "title": "Hardcoded sensitive information in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The user_data script contains hardcoded sensitive information such as the API key and database password. This can lead to credential leakage if the launch template is accessed by unauthorized users."
    },
    {
      "check_id": "CKV_AWS_23",
      "title": "Launch template does not enable detailed monitoring",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "Detailed monitoring is not enabled for the launch template. Enabling it provides enhanced visibility into instance performance and can help with troubleshooting and cost optimization."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]
  user_data = base64encode(<<-EOF
              export DATABASE_PASSWORD="${var.db_password}"
              export API_KEY="${var.api_key}"
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
  monitoring {
    enabled = true
  }
}",
  "fix_summary": "Replaced hardcoded sensitive information in user_data with references to variables to prevent credential leakage. Enabled detailed monitoring for the launch template to improve visibility into instance performance."
}
